import "server-only";
import { diskPerGb, productLd, usd, vpsPlans, vpsTermMap } from "./lib";

/** /vps — real plans, term discounts and the disk add-on price. */
export async function load(_p: Record<string, string>) {
  const [plans, terms, perGb] = await Promise.all([vpsPlans(), vpsTermMap(), diskPerGb()]);
  if (!plans.length) throw new Error("nxm /vps: no active VPS plans");
  const cheapest = Math.min(...plans.map((p) => p.p));
  const pct = (m: number) => String(Math.round((terms[m] ?? 0) * 100));
  return {
    data: { vps: plans, terms },
    jsonLd: [productLd("Nxeon Cloud VPS",
      "NVMe cloud VPS with full root access, a dedicated IPv4, snapshots, backups and DDoS protection.",
      "/vps", plans.map((p) => ({ name: `${p.n} VPS`, price: p.i ?? p.p })))],
    slots: {
      "vps.from": usd(cheapest * 100),
      "vps.fromAnnual": usd(Math.round(cheapest * 100 * (1 - (terms[12] ?? 0)))),
      "term.12": pct(12), "term.24": pct(24), "term.36": pct(36),
      "term.maxPct": String(Math.max(...Object.values(terms).map((v) => Math.round(v * 100)))),
      "disk.perGb": perGb,
    },
  };
}
