  const wait = ms => new Promise(r => setTimeout(r, RM ? 0 : ms));
  $('#dc-go').addEventListener('click', async () => { const sp = spec(recFor(+pl.value, derivedPack())), n = S.ldr === 'Vanilla' ? 0 : mods.filter(m => m.checked).length, run = $('#dc-run'), body = $('#dc-body'), list = $('#dc-steps'), ring = run.querySelector('.p'), pct = $('#dc-pct');
