    run.style.minHeight = body.offsetHeight + 'px'; body.hidden = true; run.hidden = false; run.querySelector('.dc-ok').hidden = true; list.innerHTML = steps.map(t => `<li>${t}</li>`).join(''); const lis = $$('li', list);
    for (let k = 0; k < lis.length; k++) { lis[k].className = 'run'; const v = (k + 1) / lis.length; ring.style.strokeDashoffset = (213.6 * (1 - v)).toFixed(1); pct.textContent = Math.round(v * 100) + '%'; await wait(650); lis[k].className = 'ok'; }
