  /* ---- voxel world ---- */
  let drawn = '';
  function world(idx, players) { if (!svg) return; const key = idx + ':' + players; if (key === drawn) return; const reTiles = !drawn.startsWith(idx + ':'); drawn = key;
    const n = idx + 2, w = Math.min(84, 440 / n), h = w / 2, cx = 300, top = 210 - (n * w / 4) - 10; let seed = 7 + idx * 13; const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280; const tiles = [];
    let g = svg.querySelector('g.land');
    if (reTiles || !g) { svg.innerHTML = '<defs><linearGradient id="gl" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient></defs>'; g = document.createElementNS(NS, 'g'); g.setAttribute('class', 'land'); svg.appendChild(g); }
