      if (tree) { const t = document.createElementNS(NS, 'g'); t.setAttribute('class', 'cube'); t.style.animationDelay = (s * 45 + 200) + 'ms'; const tw = w * .42;
        t.innerHTML = `<rect x="${x - tw / 6}" y="${y - tw * 1.2}" width="${tw / 3}" height="${tw * 1.3}" fill="#7A4E2A"/><polygon points="${x},${y - tw * 2.2} ${x + tw},${y - tw * 1.7} ${x},${y - tw * 1.2} ${x - tw},${y - tw * 1.7}" fill="#39B35A"/><polygon points="${x - tw},${y - tw * 1.7} ${x},${y - tw * 1.2} ${x},${y - tw * .7} ${x - tw},${y - tw * 1.2}" fill="#2A8A45"/><polygon points="${x},${y - tw * 1.2} ${x + tw},${y - tw * 1.7} ${x + tw},${y - tw * 1.2} ${x},${y - tw * .7}" fill="#23763B"/>`; g.appendChild(t); } }
    let pg = svg.querySelector('g.pins'); if (pg) pg.remove(); pg = document.createElementNS(NS, 'g'); pg.setAttribute('class', 'pins'); let ps = 99;
    const prnd = () => (ps = (ps * 9301 + 49297) % 233280) / 233280;
    for (let k = 0; k < Math.min(players, tiles.length * 2); k++) { const [px, py] = tiles[Math.floor(prnd() * tiles.length)], ox = (prnd() - .5) * w * .5, oy = (prnd() - .5) * w * .2, col = ['#3EDCF2', '#FFD27A', '#FF6FA8', '#9B8CFF', '#fff'][k % 5];
