  function fit() { const sp = spec(S.idx), used = need(S.fitPl, S.pack) / sp.gb, pct = Math.round(used * 100), bar = $('#ft-bar'), st = $('#ft-st'), up = $('#ft-up'), tag = $('#wz-tag');
