  $$('.wz-tiers button').forEach(b => b.addEventListener('click', () => { if (b.dataset.cx) custom(true); else { custom(false); setTier(+b.dataset.i); } }));
  $('#wz-cback').addEventListener('click', () => custom(false));
  const fp = $('#ft-pl'); fp.addEventListener('input', () => { S.fitPl = +fp.value; setTier(S.idx); });
