  function sticky() { const sp = spec(S.idx); $('#skb-a').textContent = `${D.name} · ${sp.gb} GB`; $('#skb-b').textContent = `${sp.cpu} vCPU · ${sp.disk} GB NVMe · ${S.reg}`;
    const p = money(sp.price); if (p !== last) { $('#skb-p').innerHTML = p + '<small>/mo</small>'; bar.classList.remove('bump'); void bar.offsetWidth; bar.classList.add('bump'); last = p; } }
  let heroOut = false, finIn = false; const vis = () => { const on = heroOut && !finIn; bar.classList.toggle('on', on); bar.setAttribute('aria-hidden', String(!on)); bar.querySelector('a').tabIndex = on ? 0 : -1; };
  new IntersectionObserver(([e]) => { heroOut = !e.isIntersecting; vis(); }, { threshold: 0 }).observe(hero);
