/* ============ Hero: cover wall parallax and live deployment toasts ============ */
(function hero() {
  const hero = $('.gh'), wall = $('#gh-wall'); if (!hero) return;
  if (!RM && window.matchMedia('(hover: hover)').matches) {
    let pend = null;
    hero.addEventListener('pointermove', e => { const first = !pend; pend = e; if (!first) return;
      requestAnimationFrame(() => { const r = hero.getBoundingClientRect(), x = (pend.clientX - r.left) / r.width - 0.5, y = (pend.clientY - r.top) / r.height - 0.5; pend = null;
        wall.style.setProperty('--wx', (x * -30).toFixed(1) + 'px'); wall.style.setProperty('--wy', (y * -20).toFixed(1) + 'px'); }); });
    hero.addEventListener('pointerleave', () => { wall.style.setProperty('--wx', '0px'); wall.style.setProperty('--wy', '0px'); });
  }
  const toast = $('#gh-toast'); if (!toast || RM) return;
  const src = k => { const img = $(`.cg[data-k="${k}"] img`); return img ? img.src : ''; };
  const EV = [['valheim', 'valheim-vikings', 'is online in Falkenstein'], ['minecraft', 'mc-survival', 'is online in Singapore'], ['rust', 'rust-weekly', 'wiped and back online in Falkenstein'],
    ['palworld', 'pal-island', 'is online in Singapore'], ['counterstrike2', 'cs2-scrims', 'is online in Falkenstein'], ['projectzomboid', 'knox-county', 'restored a backup in Singapore']];
  let i = 0, vis = true; watch(hero, v => { vis = v; });
  setInterval(() => { if (!vis || document.hidden) return; toast.classList.add('out');
    setTimeout(() => { const [k, n, t] = EV[++i % EV.length]; $('#ght-img').src = src(k); $('#ght-name').textContent = n; $('#ght-text').textContent = t; toast.classList.remove('out'); }, 480); }, 3600);
})();

/* ============ Configurator: game-by-game pricing ============ */
/* PLACEHOLDER PRICING: only 1 GB ($2.99, "from") and 2 GB ($4.99, Minecraft 2 GB in the panel) are real.
   Every other tier price and each game's sizing below is an estimate to replace with final plans. */
const TIERS = [1, 2, 4, 6, 8, 12, 16];
const PRICE = { 1: 2.99, 2: 4.99, 4: 8.99, 6: 12.99, 8: 16.99, 12: 24.99, 16: 32.99 };
const ADDON = 2.99;
const SIZING = {
  minecraft: ['Sandbox', 1, 5, 50], rust: ['Survival', 6, 12.5, 150], valheim: ['Survival', 4, 2.5, 20], palworld: ['Survival', 8, 2, 32],
  counterstrike2: ['Action and FPS', 2, 6, 24], projectzomboid: ['Survival', 4, 4, 32], arksurvivalevolv: ['Survival', 8, 3.75, 30], '7daystodie': ['Survival', 4, 2, 16],
  enshrouded: ['Survival', 4, 2.67, 16], sonsoftheforest: ['Survival', 4, 1, 8], satisfactory: ['Strategy', 6, 0.67, 8], terraria: ['Sandbox', 1, 8, 16],
  dayz: ['Survival', 4, 7.5, 60], conanexiles: ['Survival', 6, 6, 70], vrising: ['Survival', 4, 5, 40], garrysmod: ['Sandbox', 2, 10, 64]
};
(function configurator() {
  const bars = $('#cfg-bars'); if (!bars) return;
  const tiles = $$('.cg'), more = $('#cfg-more'), pl = $('#cfg-pl'), plv = $('#cfg-plv'), tip = $('#cfg-tip');
  const regBtns = $$('.cfg-reg button'), aIp = $('#a-ip'), aBk = $('#a-bk');
  let game = 'minecraft', name = 'Minecraft', sz = SIZING.minecraft, sel = 2, manual = false, shown = 0;
  const slots = t => Math.max(1, Math.min(sz[3], Math.floor(sz[2] * t)));
  const ok = t => t >= sz[1];
  const recFor = p => TIERS.find(t => ok(t) && slots(t) >= p) || TIERS[TIERS.length - 1];
  const maxP = Math.max(...Object.values(PRICE));
  bars.innerHTML = TIERS.map(t => `<button type="button" class="cb" data-t="${t}" style="--h:${(PRICE[t] / maxP).toFixed(3)}"><b>$${PRICE[t]}</b><i></i><small>${t} GB</small></button>`).join('');
  const cbs = $$('.cb', bars);
  const money = v => '$' + v.toFixed(2);
  function tween(to) {
    const el = $('#s-total'), from = shown; shown = to; if (RM) { el.textContent = money(to); return; }
    const t0 = performance.now(); const step = now => { const k = Math.min(1, (now - t0) / 450), e = 1 - Math.pow(1 - k, 3); el.textContent = money(from + (to - from) * e); if (k < 1) requestAnimationFrame(step); }; requestAnimationFrame(step);
  }
  function render() {
    const rec = recFor(+pl.value);
    if (!manual || !ok(sel) || slots(sel) < +pl.value) { sel = rec; manual = false; }
    cbs.forEach(b => { const t = +b.dataset.t; b.classList.toggle('na', !ok(t)); b.classList.toggle('rec', t === rec); b.classList.toggle('sel', t === sel);
      b.setAttribute('aria-pressed', String(t === sel)); b.setAttribute('aria-label', ok(t) ? `${t} GB, up to ${slots(t)} players, $${PRICE[t]} a month` : `${t} GB is not enough for ${name}`); });
    plv.textContent = pl.value;
    $('#cfg-hint').textContent = `Recommended: ${rec} GB for up to ${slots(rec)} players`;
    $('#s-game').textContent = name; $('#s-mem').textContent = sel + ' GB'; $('#s-slots').textContent = slots(sel);
    $('#s-cta').textContent = `Deploy ${name}`;
    tween(PRICE[sel] + (aIp.checked ? ADDON : 0) + (aBk.checked ? ADDON : 0));
  }
  function setGame(k) {
    game = k; sz = SIZING[k] || ['Game server', 4, 4, 32];
    const tile = $(`.cg[data-k="${k}"]`), opt = more.querySelector(`option[value="${k}"]`);
    name = tile ? tile.querySelector('span').textContent : (opt ? opt.textContent : k);
    tiles.forEach(t => t.setAttribute('aria-pressed', String(t === tile)));
    if (tile) more.value = '';
    const wallImg = $(`.gh-col img[data-k="${k}"]`);
    $('#cfg-poster').src = tile ? tile.querySelector('img').src : (wallImg ? wallImg.src : $('#cfg-poster').src);
    $('#cfg-name').textContent = name; $('#cfg-genre').textContent = sz[0];
    pl.max = sz[3]; pl.value = Math.min(+pl.value, sz[3]); if (!SIZING[k]) pl.value = Math.min(10, sz[3]);
    manual = false; render();
  }
  tiles.forEach(t => t.addEventListener('click', () => setGame(t.dataset.k)));
  more.addEventListener('change', () => { if (more.value) setGame(more.value); });
  pl.addEventListener('input', render);
  [aIp, aBk].forEach(c => c.addEventListener('change', render));
  regBtns.forEach(b => b.addEventListener('click', () => regBtns.forEach(x => x.setAttribute('aria-pressed', String(x === b)))));
  cbs.forEach(b => {
    b.addEventListener('click', () => { const t = +b.dataset.t; if (!ok(t)) return; sel = t; manual = true; if (slots(t) < +pl.value) pl.value = slots(t); render(); });
    b.addEventListener('pointerenter', () => { const t = +b.dataset.t, r = b.getBoundingClientRect(), br = bars.parentElement.getBoundingClientRect();
      tip.innerHTML = ok(t) ? `<b>$${PRICE[t]}/month</b>${t} GB memory<br>Up to ${slots(t)} players` : `<b>${t} GB</b>Not enough memory for ${name}`;
      tip.style.transform = `translate(${Math.min(br.width - 190, Math.max(8, r.left - br.left + r.width / 2 - 85)).toFixed(0)}px, ${(r.top - br.top - 70).toFixed(0)}px)`; tip.classList.add('show'); });
    b.addEventListener('pointerleave', () => tip.classList.remove('show'));
  });
  // any library card prices that game here
  const byName = n => { n = n.toLowerCase(); const t = tiles.find(x => x.querySelector('span').textContent.toLowerCase() === n); if (t) return t.dataset.k; const o = [...more.options].find(x => x.textContent.toLowerCase() === n); return o ? o.value : null; };
  $$('.gl-card').forEach(c => c.addEventListener('click', () => { const k = byName(c.dataset.name); if (k) setGame(k); }));
  render();
})();

/* ============ Control room: an interactive server panel ============ */
(function controlRoom() {
  const log = $('#ctl-log'); if (!log) return;
  const tabs = $$('.ctl-tabs [role=tab]'), panels = $$('.ctl-panel');
  const show = t => { tabs.forEach(x => { const on = x === t; x.setAttribute('aria-selected', String(on)); x.tabIndex = on ? 0 : -1; }); panels.forEach(p => { p.hidden = p.id !== t.getAttribute('aria-controls'); }); };
  tabs.forEach(t => t.addEventListener('click', () => show(t)));
