  const D = Math.PI / 180, gc = (a, b) => { const dLat = (b.lat - a.lat) * D, dLon = (b.lon - a.lon) * D; const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * D) * Math.cos(b.lat * D) * Math.sin(dLon / 2) ** 2; return 2 * 6371 * Math.asin(Math.sqrt(h)); };
