  const ctx = cv.getContext('2d'), mask = Uint8Array.from(atob(LANDMASK), c => c.charCodeAt(0));
  const land = (x, y) => { const i = y * 256 + x; return (mask[i >> 3] >> (i & 7)) & 1; };
