    ['fsn', 'sin'].forEach(k => { $('#rf-ms-' + k).textContent = '~' + ms[k] + ' ms'; $('#rf-bar-' + k).style.setProperty('--v', Math.min(1, Math.max(0.04, ms[k] / 300)).toFixed(3)); $('#rf-' + k).classList.toggle('best', k === best); });
