    const arc = k => { const [x, y] = proj(R[k].lat, R[k].lon), cx = (mx + x) / 2, cy = Math.min(my, y) - Math.abs(x - mx) * 0.22 - 20; return `<path class="rf-arc ${k === 'fsn' ? 'a' : 'b'}${k === best ? ' best' : ''}" d="M${mx.toFixed(1)} ${my.toFixed(1)} Q${cx.toFixed(1)} ${cy.toFixed(1)} ${x.toFixed(1)} ${y.toFixed(1)}"/>`; };
