    svg.innerHTML = arc('fsn') + arc('sin') + pin('fsn') + pin('sin') + `<circle class="rf-pin me" cx="${mx}" cy="${my}" r="6"/><text class="rf-lab" x="${mx + 10}" y="${my - 8}">${o.value}</text>`;
