export async function queryCatalogMods(opts: {
  family?: string;
  /** Category filter — the per-family page's chips (StoreBrowser's `chipField: "category"`). */
  category?: string;
  q?: string;
  sort?: CatalogSort;
  page?: number;
  perPage?: number;
}): Promise<CatalogPage> {
  const sort = opts.sort ?? "featured";
  const q = (opts.q ?? "").trim();
  const where: Prisma.GameModWhereInput = {
    active: true,
    upstreamOk: true,
    ...(opts.family ? { gameFamily: opts.family } : {}),
    ...(opts.category ? { category: opts.category } : {}),
    ...(q
      ? {
          OR: [
            { name: { contains: q, mode: "insensitive" } },
            { category: { contains: q, mode: "insensitive" } },
            { description: { contains: q, mode: "insensitive" } },
          ],
        }
      : {}),
  };

  const total = await db.gameMod.count({ where });
  const { skip, take, page, pages, perPage } = paginate(
    { page: opts.page != null ? String(opts.page) : undefined },
    total,
    opts.perPage ?? CATALOG_PAGE_SIZE
  );

  const rows = await db.gameMod.findMany({ where, orderBy: ORDER_BY[sort], skip, take });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  const mods = rows.map((r) => toSummary(r, aggs.get(r.id)));
  if (sort === "rating") {
    mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
  }

  return { mods, total, page, totalPages: pages, perPage };
}

