import "server-only";
import fs from "node:fs";
import path from "node:path";
import { db } from "@/lib/db";
import { deployHref } from "@/lib/deploy-intent";
import { planIntroMonthlyCents, planIntroTermMonths } from "@/lib/intro-pricing";
import { GAME_ART_SLUG, GAME_DISPLAY, GAME_FAMILIES, GAME_GENRES, type GameFamily } from "@/lib/games";
import { CUSTOMER_REGION_LABELS, REGION_COORDS, REGION_COUNTRY, REGION_LABELS } from "@/lib/node-regions";
import { formatDownloads, SOURCE_LABEL, type ModSummary } from "@/lib/mods-catalog";
import GAME_ROUTE_ROWS from "../../../tools/nxm/routes/minecraft-server-hosting.json";
import { esc, introSpan, usd } from "./lib";

/**
 * Shared, real-data helpers for the game-server pages of the new marketing
 * site (hub, game template, game x location template, free Minecraft).
 *
 * Sellable = a family with ACTIVE db.gamePlan rows (what checkout sells);
 * regions = enabled db.node rows. Both are read at request time.
 */

// ── routes ──────────────────────────────────────────────────────────────────
/** Staged prefix: every game route is served under /nxm until launch
 *  (NXM_LIVE=1 at launch, the same switch _seo/meta.ts uses). */
const BASE = process.env.NXM_LIVE === "1" ? "" : "/nxm";
export const staged = (route: string) => BASE + route;

/** family -> production route, from the fan-out file the port wrote
 *  (tools/nxm/routes/minecraft-server-hosting.json — the live site's paths). */
const ROUTE_OF: Record<string, string> = Object.fromEntries(
  (GAME_ROUTE_ROWS as { route: string; params: { family: string } }[]).map((r) => [r.params.family, r.route]),
);
export const gameRoute = (family: string): string | null => ROUTE_OF[family] ?? null;

/** A region's URL segment: its customer-facing label, lower-cased (the port's
 *  tools/nxm/wire/_games.py region_slug uses the same rule). */
export const regionLabel = (code: string) => CUSTOMER_REGION_LABELS[code as keyof typeof CUSTOMER_REGION_LABELS] ?? code;
export const regionSlug = (code: string) => regionLabel(code).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

// ── catalogue ──────────────────────────────────────────────────────────────
export const gameName = (family: string) => GAME_DISPLAY[family as GameFamily]?.name ?? family;
export const isGameFamily = (family: string) => (GAME_FAMILIES as readonly string[]).includes(family);
export const gameGenres = (family: string) => GAME_GENRES[family as GameFamily] ?? [];
/** "world" for games you build/survive in, "server" for match-based shooters. */
export const worldWord = (family: string) =>
  gameGenres(family).some((g) => g === "Survival" || g === "Sandbox" || g === "RPG" || g === "Strategy") ? "world" : "server";

export type RealTier = {
  id: string; name: string; ram: number; cpu: number; disk: number; slots: number | null;
  /** regular monthly price, dollars */ p: number;
  /** intro monthly price, dollars, or null */ i: number | null;
  /** "first month" / "first 3 months" when an intro rate applies */ is: string;
  featured: boolean;
  /** deploy link per live region code */ href: Record<string, string>;
};

const gb = (mb: number) => Math.round((mb / 1024) * 10) / 10;

/** A family's active tiers (the rows checkout sells), cheapest first, with a
 *  deploy link for every live region. */
export async function realTiers(family: string, regions: string[]): Promise<RealTier[]> {
  const rows = await db.gamePlan.findMany({
    where: { active: true, gameFamily: family },
    orderBy: [{ ramMB: "asc" }, { sortOrder: "asc" }],
  });
  return rows.map((g) => {
    const perMonth = (c: number) => (g.termMonths > 1 ? c / g.termMonths : c);
    const intro = planIntroMonthlyCents(g);
    return {
      id: g.id, name: g.name, ram: gb(g.ramMB), cpu: g.cpuCores, disk: g.diskGB, slots: g.slots,
      p: perMonth(g.priceCents) / 100, i: intro == null ? null : perMonth(intro) / 100,
      is: intro == null ? "" : introSpan(planIntroTermMonths(g)), featured: g.featured,
      href: Object.fromEntries(regions.map((r) => [r, deployHref({ service: "game", gameFamily: family, gamePlanId: g.id, region: r })])),
    };
  });
}

/** Every sellable family (has active plans), in catalogue order, with its
 *  tiers' from-price / max slots — one query. */
export async function sellableGames() {
  const rows = await db.gamePlan.findMany({
    where: { active: true },
    select: { gameFamily: true, priceCents: true, introPriceCents: true, introTermMonths: true, termMonths: true, slots: true, ramMB: true, id: true, featured: true },
  });
  const by = new Map<string, typeof rows>();
  for (const r of rows) by.set(r.gameFamily, [...(by.get(r.gameFamily) ?? []), r]);
  return GAME_FAMILIES.filter((f) => by.has(f)).map((f) => {
    const ts = by.get(f)!;
    const monthly = ts.map((t) => {
      const intro = planIntroMonthlyCents(t);
      return (intro ?? t.priceCents) / (t.termMonths > 1 ? t.termMonths : 1);
    });
    const slots = ts.map((t) => t.slots).filter((s): s is number => s != null);
    return {
      family: f as string, name: gameName(f), genres: gameGenres(f), route: gameRoute(f),
      fromCents: Math.round(Math.min(...monthly)), maxSlots: slots.length ? Math.max(...slots) : null, tiers: ts.length,
    };
  });
}
export type SellableGame = Awaited<ReturnType<typeof sellableGames>>[number];

// ── regions ────────────────────────────────────────────────────────────────
/** Regions a customer can deploy into (enabled nodes), primary node's first. */
export async function deployRegions() {
  const nodes = await db.node.findMany({ where: { enabled: true }, select: { region: true, isPrimary: true } });
  const codes = [...new Set(nodes.sort((a, b) => Number(b.isPrimary) - Number(a.isPrimary)).map((n) => n.region))];
  return codes.map((code) => ({
    code, label: regionLabel(code), city: REGION_LABELS[code] ?? regionLabel(code), cc: REGION_COUNTRY[code] ?? "",
    coords: REGION_COORDS[code] ?? null, info: REGION_INFO[code] ?? null, slug: regionSlug(code),
  }));
}
export type DeployRegion = Awaited<ReturnType<typeof deployRegions>>[number];

/** Geography per region for the game x location pages: facts only (where the
 *  region is, nearby cities and their coordinates, the region's timezone, the
 *  design's map crop). No latency figures: the pages show real straight-line
 *  distances computed from these coordinates. */
type City = { name: string; cc: string; lat: number; lon: number; anchor: "l" | "r" | "t" | "b" };
export const REGION_INFO: Record<string, { area: string; continent: string; blurb: string; tz: string; map: "apac" | "eu"; acc: string; cities: City[] }> = {
