    : `<div class="dc-r"><span class="dc-l">Region</span><div class="rgc" id="b-reg" role="group" aria-label="Region" style="grid-template-columns:repeat(${Math.min(c.regions.length, 3)},minmax(0,1fr))">${c.regions.map((r, i) => `<button type="button" aria-pressed="${i === 0}" data-r="${esc(r.code)}">${r.cc ? `<span class="flag flag-${r.cc}"></span>` : ""}<b>${esc(r.label)}</b><small>${esc(r.info?.continent ?? r.city)}</small></button>`).join("")}</div></div>`;
  const top = c.region
    ? `<span class="dc-lock">${c.region.cc ? `<span class="flag flag-sm flag-${c.region.cc}"></span>` : ""}${esc(c.region.label)}</span>`
    : `<span class="dc-live"><i></i>Ready to deploy</span>`;
  const href = t.href[c.R.code];
  return `<div class="dcon" id="bld" aria-label="Deploy a ${esc(c.name)} server">
      <div class="dc-top">${art.cover ? `<img src="${esc(art.cover)}" alt="" width="44" height="60">` : ""}<div><b>Deploy ${esc(c.name)}</b><small>Live in about a minute</small></div>${top}</div>
      <div class="dc-body" id="dc-body">
        <div class="dc-row2"${ver ? "" : ' style="grid-template-columns:1fr"'}><div class="dc-r"><label class="dc-l" for="b-name">Server name</label><input id="b-name" class="dc-in" value="${sname}" maxlength="24" autocomplete="off" spellcheck="false"></div>${ver}</div>
        ${ldr}
        <div class="dc-r"><span class="dc-l">Players <b id="b-plv">${c.players}</b></span><div class="dc-pl"><div class="au-range"><input type="range" id="b-pl" min="1" max="${c.maxPlayers}" value="${c.players}" aria-label="Players"><span class="au-bub"></span></div><div class="avs" id="avs" aria-hidden="true"></div></div></div>
        ${mods}
        ${reg}
        <div class="dc-out"><div class="dc-res"><span><i class="ri-cpu"></i><b id="b-cpu">${t.cpu} vCPU</b></span><span><i class="ri-ram"></i><b id="b-ram">${t.ram} GB</b> RAM</span><span><i class="ri-disk"></i><b id="b-disk">${t.disk} GB</b> NVMe</span></div><div class="dc-price"><b id="b-price">${money(priceOf(t))}</b><small id="b-per">${t.i != null ? esc(t.is) : "/month"}</small></div></div>
        <button type="button" class="adp-go dc-go" id="dc-go"><span class="adp-go-t">Deploy <em id="b-nm">${sname}</em></span></button>
        <p class="bld-fine"><span id="b-sum"></span> · Cancel anytime</p>
        <p class="dc-cust" id="dc-cust" hidden>Need more than ${c.topT.ram} GB? <a href="#custom">We’ll build you a custom server →</a></p>
      </div>
      <div class="dc-run" id="dc-run" hidden><div class="dc-ring"><svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="34"/><circle class="p" cx="40" cy="40" r="34"/></svg><b id="dc-pct">0%</b></div><ol class="dc-steps" id="dc-steps"></ol>
        <div class="dc-ok" hidden><b id="dc-okt">${sname} is ready to order</b><small id="dc-oks"></small><a class="adp-go" href="${esc(href)}"><span class="adp-go-t">Continue to checkout →</span></a><button type="button" class="dc-back" id="dc-back">Change something</button></div></div>
    </div>`;
}

function loadersHtml(c: Ctx) {
  if (!c.variants.length) return "";
  const dv = c.schema!.defaultVariant;
  const tabs = c.variants.map((v) => `<button type="button" data-l="${esc(v.id)}" aria-pressed="${v.id === dv}"><b>${esc(v.label)}</b><small>${esc((v.description ?? "").split(/ — |\. |\.$/)[0])}</small></button>`).join("");
  const panels = c.variants.map((v) => `<div class="ldr-p" data-l="${esc(v.id)}"${v.id === dv ? "" : " hidden"}><h3>${esc(v.label)}</h3><p>${esc(v.description ?? "")}</p></div>`).join("");
  return `<section class="section" id="loaders" aria-labelledby="ld-title" style="padding-top:0"><div class="container ldr"><div><h2 class="h2" id="ld-title">Every server type, one switch</h2><p class="lede">Choose how your ${esc(c.name)} server runs when you deploy it.</p><div class="ldr-t" role="tablist">${tabs}</div></div><div class="ldr-v au-glass">${panels}</div></div></section>`;
}

function modsHtml(c: Ctx) {
  if (!c.mods.length) return "";
  const info = MOD_INFO[c.family as GameFamily];
  const h = c.oneClick ? `${c.modCount.toLocaleString("en-US")} ${c.name} mods, one click each` : `${c.modCount.toLocaleString("en-US")} ${c.name} mods on NxLabs`;
  const lede = c.oneClick
    ? "Supported mods install straight onto your server from the panel. No uploads, no guessing folders."
    : `${info?.blurb ?? ""} ${info?.note ?? ""}`.trim();
  const cards = c.mods.map((m, i) => modCard(m, `g${i}`, c.ranked ? i : null)).join("");
  return `<section class="section mrow-s" id="mods" aria-labelledby="md-title" style="padding-top:0"><div class="container">
  <div class="nxb"><img src="/nxm/games/nxlabs_logo.webp" alt="NxLabs" width="190" height="54"><div><h2 class="h2" id="md-title">${esc(h)}</h2><p class="lede">${esc(lede)}</p></div></div>
  <div class="mrow-h mrow-h2"><div></div><div class="mrow-c"><a class="va" href="${esc(staged(`/mods/games/${c.family}`))}">Browse ${esc(c.name)} mods<span aria-hidden="true">→</span></a><button type="button" class="cb prev" aria-label="Previous">‹</button><button type="button" class="cb next" aria-label="Next">›</button></div></div>
  <div class="mrow" tabindex="0" aria-label="Popular ${esc(c.name)} mods">${cards}</div></div></section>`;
}

const regionLink = (c: Ctx, r: DeployRegion) =>
  `<a class="gl-reg" href="${esc(staged(`${c.route}/${r.slug}`))}">${r.cc ? `<span class="flag flag-${r.cc}"></span>` : ""}<div><b>${esc(c.name)} in ${esc(r.label)}</b><small>${esc(r.info?.blurb ?? r.city)}</small></div><span class="gl-go">→</span></a>`;

function moreHtml(c: Ctx) {
  const hub = staged("/game-servers");
  if (!c.region) {
    const big = c.freeMc
      ? `<a class="gl-free" href="${esc(staged("/free-minecraft"))}"><span class="au-chip"><i class="d"></i>Free forever tier</span><h2>Not ready to pay? Try it free.</h2><p>A free ${esc(c.name)} server with no card and no queue. Upgrade in one click when your friends show up.</p><span class="gl-go">Get a free server →</span></a>`
      : `<a class="gl-free" href="${esc(hub)}"><span class="au-chip"><i class="d"></i>${c.games.length} games</span><h2>Playing more than one game?</h2><p>Every game on Nxeon runs from the same account and panel, from ${money(Math.min(...c.games.map((g) => g.fromCents)) / 100)} a month.</p><span class="gl-go">See every game →</span></a>`;
    return `<section class="section" id="more" style="padding-top:0"><div class="container gloc">${big}${c.regions.map((r) => regionLink(c, r)).join("")}</div></section>`;
  }
  const others = c.regions.filter((r) => r.code !== c.region!.code).map((r) => regionLink(c, r)).join("");
  const all = `<a class="gl-reg" href="${esc(staged(c.route))}"><span class="gl-ic">${I("game")}</span><div><b>All ${esc(c.name)} hosting</b><small>Every region${c.variants.length ? ", server type" : ""} and plan</small></div><span class="gl-go">→</span></a>`;
  const last = c.freeMc
    ? `<a class="gl-reg" href="${esc(staged("/free-minecraft"))}"><span class="gl-ic">${I("spark")}</span><div><b>Try ${esc(c.name)} free</b><small>No card, no queue</small></div><span class="gl-go">→</span></a>`
    : `<a class="gl-reg" href="${esc(hub)}"><span class="gl-ic">${I("spark")}</span><div><b>Every game</b><small>${c.games.length} games, one account</small></div><span class="gl-go">→</span></a>`;
  return `<section class="section" id="more" style="padding-top:0"><div class="container glinks">${all}${others}${last}</div></section>`;
}

function faqItems(c: Ctx) {
  const where = c.region ? ` in ${c.region.city}` : "";
  const t = c.tiers;
  const plans = t.map((x) => `${x.ram} GB${x.slots != null ? ` with ${x.slots} player slots` : ""} at ${money(priceOf(x))} a month${x.i != null ? ` (${x.is}, then ${money(x.p)})` : ""}`);
  const vlabels = c.variants.map((v) => v.label);
  const info = MOD_INFO[c.family as GameFamily];
  const modsA = c.oneClick && c.modCount
    ? `Yes. ${vlabels.length ? `Pick ${orList(vlabels)} when you deploy, then add` : "Add"} supported mods from NxLabs to your server in one click, or upload your own files.`
    : info ? `${info.blurb} ${info.note}` : "You get full file access to add mods and configs yourself.";
  const Q: [string, string][] = [
    ["Which size do I need?", `${c.name} comes in ${t.length} size${t.length === 1 ? "" : "s"}: ${list(plans)}. The picker above recommends one for your player count${c.withMods ? " and mods" : ""}, and you can resize later.`],
    ["Will my server lag?", `Your server runs on NVMe hardware${where}, and the size picker recommends enough memory for your players${c.withMods ? " and mods" : ""}. If you grow, resize from the panel in a click.`],
    ["What happens if my server gets attacked?", `Every game server sits behind the Nxeon Shield: five layers of DDoS filtering that scrub attack traffic before it reaches your ${c.world}.`],
    [`Are my ${c.world}s backed up?`, `Every server includes ${BACKUP_FREE_KEEP} daily restore points. Add Plus retention to keep ${BACKUP_PLUS_KEEP}, a full week.`],
    ["Can I install mods and plugins?", modsA],
    [c.verField ? "Can I change size or version later?" : "Can I change size later?", `Yes. Resize${c.verField ? " and switch versions" : ""} from the panel whenever your community is ready.`],
    ...(c.region ? [] as [string, string][] : [["Where are the servers?", `${c.name} servers run in ${list(c.regions.map((r) => r.label))}. Pick the region closest to most of your players when you deploy.`] as [string, string]]),
    ["Do you offer custom servers for big communities?", `Yes. If you need more than ${c.topT.ram} GB, a network of linked servers or dedicated hardware, talk to us and we’ll size and quote a custom setup.`],
    ["Can I cancel anytime?", `Yes. There’s no lock-in${c.freeMc ? `, and you can try ${c.name} on the free tier before you pay anything` : ""}.`],
  ];
  return Q;
}
function faqHtml(c: Ctx) {
  return `<section class="section" id="faq" aria-labelledby="faq-title" style="padding-top:0"><div class="container faq-wrap"><div><h2 class="h2" id="faq-title">Before you deploy</h2><p class="lede">The questions people ask right before they start.</p></div><div class="faq">${faqItems(c).map(([q, a], i) => `<details${i === 0 ? " open" : ""}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("")}</div></div></section>`;
}

function pingHtml(c: Ctx) {
  const r = c.region!, info = r.info!, m = MAPS[info.map], dc = r.coords;
  if (!dc) throw new Error(`nxm games: no REGION_COORDS for ${r.code}`);
  const proj = (lat: number, lon: number) => [((lon - m.lon[0]) / (m.lon[1] - m.lon[0])) * m.W, ((m.lat[1] - lat) / (m.lat[1] - m.lat[0])) * m.H];
  const [dx, dy] = proj(dc.lat, dc.lon);
  const BANDS: [number, string, string][] = [[1000, "Under 1,000 km", "#3FD89A"], [2500, "Under 2,500 km", "#3EDCF2"], [Infinity, "Farther", "#9B8CFF"]];
  let arcs = "", labels = "", lst = "";
  info.cities.forEach((city, n) => {
    const [x, y] = proj(city.lat, city.lon), k = `c${n}`, km = distanceKm(dc, city), band = BANDS.find(([lim]) => km < lim)!, tc = band[2];
    const mx = (dx + x) / 2, my = (dy + y) / 2, dist = Math.hypot(x - dx, y - dy);
    let nx = -(y - dy) / (dist || 1), ny = (x - dx) / (dist || 1);
    if (ny > 0) { nx = -nx; ny = -ny; }
    const cx = mx + nx * dist * 0.28, cy = my + ny * dist * 0.28;
    arcs += `<path id="a${n}" class="arc" data-k="${k}" style="--tc:${tc}" d="M${dx.toFixed(0)} ${dy.toFixed(0)} Q${cx.toFixed(0)} ${cy.toFixed(0)} ${x.toFixed(0)} ${y.toFixed(0)}"/><circle class="pkt" r="5"><animateMotion dur="${(1.6 + dist / 900).toFixed(1)}s" repeatCount="indefinite" begin="${(n * 0.35).toFixed(2)}s"><mpath href="#a${n}"/></animateMotion></circle><circle class="cd" style="--tc:${tc}" cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="9"/>`;
    labels += `<span class="gl ${city.anchor}" data-k="${k}" style="left:${((x / m.W) * 100).toFixed(2)}%;top:${((y / m.H) * 100).toFixed(2)}%;--tc:${tc}"><span class="flag flag-${city.cc}"></span>${esc(city.name)}</span>`;
    lst += `<li data-k="${k}" style="--tc:${tc}"><span class="flag flag-${city.cc}"></span>${esc(city.name)}<em>${Math.round(km / 10) * 10 < 1000 ? Math.round(km / 10) * 10 : Math.round(km / 50) * 50 >= 1000 ? (Math.round(km / 50) * 50).toLocaleString("en-US") : Math.round(km)} km</em></li>`;
  });
  labels += `<span class="gl dc b" style="left:${((dx / m.W) * 100).toFixed(2)}%;top:${((dy / m.H) * 100).toFixed(2)}%">${r.cc ? `<span class="flag flag-${r.cc}"></span>` : ""}${esc(r.city)}</span>`;
  return `<section class="section gmp" id="ping" aria-labelledby="pg-title"><div class="container gmp-in">
  <div class="gmp-map"><div class="gmap" id="gmap" style="aspect-ratio:${m.W}/${m.H}" aria-hidden="true"><img src="/nxm/games/maps/${info.map}.webp" alt="" width="${m.W}" height="${m.H}"><svg viewBox="0 0 ${m.W} ${m.H}" preserveAspectRatio="xMidYMid meet"><defs><radialGradient id="dcg"><stop offset="0" stop-color="${info.acc}" stop-opacity=".55"/><stop offset="1" stop-color="${info.acc}" stop-opacity="0"/></radialGradient></defs><circle cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="180" fill="url(#dcg)"/>${arcs}<circle class="dcp" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="14"/><circle class="dcp d2" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="14"/><circle class="dc0" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="11"/></svg>${labels}</div></div>
  <div><h2 class="h2" id="pg-title">Where your players connect from</h2><p class="lede">How far the cities your players live in are from ${esc(r.city)}. Closer usually means lower ping; real latency also depends on each player’s connection. Hover a city to see its route.</p><div class="lat au-glass glat" id="lat"><div class="lat-h"><b>Distance to your players</b><span class="lat-leg"><i class="t1"></i>${BANDS[0][1]}<i class="t2"></i>${BANDS[1][1]}<i class="t3"></i>${BANDS[2][1]}</span></div><ul>${lst}</ul></div></div>
</div></section>`;
}

// ── the page ───────────────────────────────────────────────────────────────
export async function gamePage(p: Record<string, string>, loc: boolean): Promise<NxmLoad> {
  const c = await context(p.family, loc ? p.region : null);
  const t = c.tiers[c.def];
  const art = gameArt(c.family);
  const r = c.region;
  const artStyle = art.hero ? (art.designHero ? `background-image:url(${art.hero})` : `background-image:url(${art.hero});background-size:cover;background-position:center 30%`) : "";
  const version = !!c.verField, types = c.variants.length > 0, cmods = c.consoleMods.length > 0;
  const subBits = [version && types ? "Pick a version and a server type" : version ? "Pick a version" : types ? `Pick ${orList(c.variants.map((v) => v.label))}` : "Pick a size for your group",
    cmods ? "add mods from NxLabs in one click" : c.modCount ? `browse ${c.modCount.toLocaleString("en-US")} ${c.name} mods on NxLabs` : ""].filter(Boolean);
  const pickBits = [version ? "version" : "", types ? "server type" : "", "size", cmods ? "mods" : ""].filter(Boolean);
  const cores = Math.max(2, ...c.tiers.map((x) => x.cpu));
  const packHtml = c.pack
    ? `<div class="fit-r"><span>Pack</span><div class="bseg fit-pk" id="ft-pk" role="group" aria-label="Pack weight">${Object.entries(c.pack).map(([k, [, n]]) => `<button type="button" data-p="${k}" aria-pressed="${k === "light"}">${n}</button>`).join("")}</div></div>`
    : "";
  const pr = priceOf(t);
  const slots: Record<string, string> = {
    "art.style": artStyle,
    "hero.chip": `${c.name} server hosting`,
    "hero.h1a": r ? `${c.name} servers in ${r.label}.` : `Your ${c.name} ${c.world},`,
    "hero.h1b": r ? `Low ping across ${r.info!.area}.` : "online in about a minute.",
    "hero.sub": r
      ? `Host your ${c.world} close to your players in ${r.info!.area}. Every server runs on NVMe in ${r.city} behind five layers of DDoS defense.`
      : `${subBits.join(", ")}, and play behind five layers of DDoS protection with daily restore points included.`,
    "console:html": consoleHtml(c),
    "wz.tiers:html": `<div class="wz-tiers" role="group" aria-label="Server size" style="grid-template-columns:repeat(${c.tiers.length + 1},minmax(0,1fr))">${c.tiers.map((x, i) => `<button type="button" data-i="${i}" aria-pressed="${i === c.def}"><b>${x.ram} GB</b><small>${money(priceOf(x))}</small></button>`).join("")}<button type="button" class="wz-cx" data-cx="1" aria-pressed="false"><b>Custom</b><small>Big communities</small></button></div>`,
    "wz.cpu": `${t.cpu} vCPU`, "wz.cores:html": "<i></i>".repeat(cores), "wz.ram": `${t.ram} GB`, "wz.disk": `${t.disk} GB`,
    "wz.players": String(c.players), "wz.max": String(c.maxPlayers), "wz.pack:html": packHtml,
    "wz.price": money(pr), "wz.per": `${t.i != null ? `${t.is}, then ${money(t.p)}/mo · ` : ""}${money(pr / Math.max(1, c.players))} per player at ${c.players}`,
    "wz.href": t.href[c.R.code], "wz.go": `Deploy ${t.ram} GB · ${money(pr)}/mo`,
    "top.ram": String(c.topT.ram),
    "custom.sized": `Sized to your player count${c.withMods ? " and mods" : ""}`,
    "custom.lede": `When you outgrow ${c.topT.ram} GB, or need a whole network of ${c.name} servers, we’ll design a setup around your players${c.withMods ? ", your mods" : ""} and your growth.`,
    "loaders:html": loadersHtml(c), "mods:html": modsHtml(c), "more:html": moreHtml(c), "faq:html": faqHtml(c),
    "flow.pick": `${cap(list(pickBits))}, all on one page.`,
    "flow.boot": `We install ${c.name}${cmods ? " and your mods" : ""}${r ? ` in ${r.label}` : ""}.`,
    "final.h": `Your ${c.world} is waiting${r ? ` in ${r.label}` : ""}.`,
    "final.alt:html": c.freeMc
      ? `<a class="nxm-glassbtn" href="${esc(staged("/free-minecraft"))}"><span class="nxm-bt">Try free first</span></a>`
      : `<a class="nxm-glassbtn" href="${esc(staged("/game-servers"))}"><span class="nxm-bt">See every game</span></a>`,
    "skb.a": `${c.name} · ${t.ram} GB`, "skb.b": `${t.cpu} vCPU · ${t.disk} GB NVMe · ${c.R.label}`,
  };
  if (r) {
    const city = cityArt(r.code);
    slots["loc.style"] = city ? `background-image:url(${city})` : "";
    slots["loc.flag"] = r.cc ? `flag-${r.cc}` : "";
    slots["loc.chip"] = `${c.name} · ${r.label}`;
    slots["loc.bullet"] = `Hosted in ${r.city}`;
    slots["ping:html"] = pingHtml(c);
  }
  const route = r ? `${c.route}/${r.slug}` : c.route;
  const desc = await describe(c);
  return {
    slots,
    data: {
      name: c.name, family: c.family,
      tiers: c.tiers.map((x) => ({ ram: x.ram, cpu: x.cpu, disk: x.disk, slots: x.slots, p: x.p, i: x.i, is: x.is, href: x.href })),
      def: c.def, players: c.players, maxRam: c.topT.ram, maxDisk: Math.max(...c.tiers.map((x) => x.disk)),
      curve: { base: c.curve.ramBaseMB, per: c.curve.ramPerPlayerMB }, pack: c.pack,
      regions: c.regions.map((x) => ({ code: x.code, label: x.label })), region: c.R.code,
      variant: c.variants.length ? c.schema!.defaultVariant : null, variants: c.variants.length > 0, variantParam: DEPLOY_PARAM.gameVariant,
      tz: r?.info?.tz ?? null,
    },
    jsonLd: [productLd(r ? `${c.name} server hosting in ${r.label}` : `${c.name} server hosting`, desc, route,
      c.tiers.map((x) => ({ name: `${c.name} ${x.ram} GB${x.slots != null ? ` / ${x.slots} slots` : ""}`, price: priceOf(x) })))],
    crumb: r ? r.label : `${c.name} server hosting`,
  };
}

async function describe(c: Ctx) {
  const from = money(Math.min(...c.tiers.map(priceOf)));
  const slots = c.tiers.map((x) => x.slots).filter((s): s is number => s != null);
  const size = `${c.tiers.length} plan${c.tiers.length === 1 ? "" : "s"} from ${c.tiers[0].ram} to ${c.topT.ram} GB${slots.length ? ` with up to ${Math.max(...slots)} player slots` : ""}`;
  return c.region
    ? `${c.name} servers in ${c.region.label} from ${from}/mo: ${size}, five-layer DDoS protection and daily restore points. Live in about a minute.`
    : `${c.name} server hosting from ${from}/mo: ${size}, servers in ${list(c.regions.map((r) => r.label))}, five-layer DDoS protection and daily restore points.`;
}

export async function gameMeta(p: Record<string, string>, loc: boolean) {
  const c = await context(p.family, loc ? p.region : null);
  const art = gameArt(c.family);
  const r = c.region;
  return {
    title: r ? `${c.name} Server Hosting in ${r.label}` : `${c.name} Server Hosting — Instant Setup, From ${money(Math.min(...c.tiers.map(priceOf)))}/mo`,
    description: await describe(c),
    crumb: r ? r.label : `${c.name} server hosting`,
    ...(art.hero ? { image: art.hero } : {}),
  };
}

