            "const R = Object.fromEntries(__NXM.regions.map(r => [r.code, r])), RK = Object.keys(R);")
    a = s.index("    const ms = { fsn:"); b = s.index("$('#rf-' + k).classList.toggle('best', k === best); });", a) + len("$('#rf-' + k).classList.toggle('best', k === best); });")
    s = s[:a] + """    const km = Object.fromEntries(RK.map(k => [k, gc(me, R[k])]));
    const best = RK.reduce((a, k) => km[k] < km[a] ? k : a, RK[0]);
    RK.forEach(k => { $('#rf-km-' + k).textContent = Math.round(km[k] / 50) * 50 < 1000 ? '~' + Math.max(10, Math.round(km[k] / 10) * 10) + ' km' : '~' + (Math.round(km[k] / 50) * 50).toLocaleString('en-US') + ' km'; $('#rf-bar-' + k).style.setProperty('--v', Math.min(1, Math.max(0.04, km[k] / 16000)).toFixed(3)); $('#rf-' + k).classList.toggle('best', k === best); });""" + s[b:]
