CONFIGURATOR = r"""/* ============ Configurator: game-by-game pricing (real tiers, db.gamePlan) ============ */
(function configurator() {
  const bars = $('#cfg-bars'); if (!bars) return;
  const G = __NXM.cfg.games, IP = __NXM.cfg.ip, AP = __NXM.cfg.addonParam;
  const tiles = $$('.cg'), more = $('#cfg-more'), pl = $('#cfg-pl'), plv = $('#cfg-plv'), tip = $('#cfg-tip');
  const regBtns = $$('.cfg-reg button'), aIp = $('#a-ip');
  let game = __NXM.cfg.first, sz = G[game], sel = 0, manual = false, shown = 0, cbs = [];
  let reg = (regBtns.find(b => b.getAttribute('aria-pressed') === 'true') || regBtns[0]).dataset.r;
  const money = v => '$' + v.toFixed(2), price = t => t.i != null ? t.i : t.p;
  const fits = (t, p) => t.slots == null || t.slots >= p;
  const recFor = p => { const i = sz.t.findIndex(t => fits(t, p)); return i < 0 ? sz.t.length - 1 : i; };
  const cta = $('#s-cta'), ctaT = $('.nxm-bt', cta) || cta;
  function tween(to) {
    const el = $('#s-total'), from = shown; shown = to; if (RM) { el.textContent = money(to); return; }
    const t0 = performance.now(); const step = now => { const k = Math.min(1, (now - t0) / 450), e = 1 - Math.pow(1 - k, 3); el.textContent = money(from + (to - from) * e); if (k < 1) requestAnimationFrame(step); }; requestAnimationFrame(step);
  }
  function href() { let h = sz.t[sel].href[reg]; if (aIp && aIp.checked && IP > 0) { const u = new URL(h, location.origin); u.searchParams.set(AP, 'ip'); h = u.pathname + u.search; } return h; }
  function render() {
    const p = +pl.value, rec = recFor(p);
    if (!manual || !fits(sz.t[sel], p)) { sel = rec; manual = false; }
    cbs.forEach((b, i) => { const t = sz.t[i]; b.classList.toggle('rec', i === rec); b.classList.toggle('sel', i === sel);
      b.setAttribute('aria-pressed', String(i === sel)); b.setAttribute('aria-label', `${t.ram} GB${t.slots != null ? ', up to ' + t.slots + ' players' : ''}, ${money(price(t))} a month`); });
    plv.textContent = p; const r = sz.t[rec], t = sz.t[sel];
    $('#cfg-hint').textContent = `Recommended: ${r.ram} GB` + (r.slots != null ? ` for up to ${r.slots} players` : '');
    $('#s-game').textContent = sz.n; $('#s-mem').textContent = t.ram + ' GB'; $('#s-slots').textContent = t.slots != null ? t.slots : '—';
    ctaT.textContent = `Deploy ${sz.n}`; cta.href = href();
    tween(price(t) + (aIp && aIp.checked ? IP / 100 : 0));
  }
  function build() {
    const maxP = Math.max(...sz.t.map(price));
    bars.innerHTML = sz.t.map((t, i) => `<button type="button" class="cb" data-i="${i}" style="--h:${(price(t) / maxP).toFixed(3)}"><b>${money(price(t))}</b><i></i><small>${t.ram} GB</small></button>`).join('');
    cbs = $$('.cb', bars);
    cbs.forEach(b => {
      b.addEventListener('click', () => { const i = +b.dataset.i, t = sz.t[i]; sel = i; manual = true; if (t.slots != null && t.slots < +pl.value) pl.value = t.slots; render(); });
      b.addEventListener('pointerenter', () => { const t = sz.t[+b.dataset.i], r = b.getBoundingClientRect(), br = bars.parentElement.getBoundingClientRect();
        tip.innerHTML = `<b>${money(price(t))}/month</b>${t.ram} GB memory` + (t.slots != null ? `<br>Up to ${t.slots} players` : '');
        tip.style.transform = `translate(${Math.min(br.width - 190, Math.max(8, r.left - br.left + r.width / 2 - 85)).toFixed(0)}px, ${(r.top - br.top - 70).toFixed(0)}px)`; tip.classList.add('show'); });
      b.addEventListener('pointerleave', () => tip.classList.remove('show'));
    });
  }
  function setGame(k) {
    if (!G[k]) return; game = k; sz = G[k];
    const tile = $(`.cg[data-k="${k}"]`);
    tiles.forEach(t => t.setAttribute('aria-pressed', String(t === tile)));
    more.value = tile ? '' : k;
    if (sz.img) $('#cfg-poster').src = sz.img;
    $('#cfg-name').textContent = sz.n; $('#cfg-genre').textContent = sz.g;
    pl.max = sz.max; pl.value = Math.min(+pl.value, sz.max);
    manual = false; build(); render();
  }
  tiles.forEach(t => t.addEventListener('click', () => setGame(t.dataset.k)));
  more.addEventListener('change', () => { if (more.value) setGame(more.value); });
  pl.addEventListener('input', render);
  if (aIp) aIp.addEventListener('change', render);
  regBtns.forEach(b => b.addEventListener('click', () => { regBtns.forEach(x => x.setAttribute('aria-pressed', String(x === b))); reg = b.dataset.r; render(); }));
  // a library card prices its game here (without JS it links to the game's page)
  $$('.gl-card').forEach(c => c.addEventListener('click', e => { if (!G[c.dataset.key]) return; e.preventDefault(); setGame(c.dataset.key); $('#configure').scrollIntoView({ behavior: RM ? 'auto' : 'smooth' }); }));
  build(); render();
})();
"""

