import "server-only";
import { GENRE_ORDER } from "@/lib/games";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { BACKUP_FREE_KEEP } from "@/lib/backup-tiers";
import { INSTALLABLE_FAMILIES } from "@/lib/mod-install-support";
import { listCatalogFamilies } from "@/lib/mods-catalog";
import { DEPLOY_PARAM } from "@/lib/deploy-intent";
import { esc, productLd, usd, type NxmLoad } from "./lib";
import { deployRegions, gameArt, money, sellableGames, staged, tiersByFamily, type RealTier } from "./games-lib";

/**
 * /game-servers — the hub (build_games2.py). Every game, count, price, tier,
 * region and cover comes from the system at request time:
 * sellable games = families with active db.gamePlan rows (lib/games.ts names,
 * genres and art); tiers per game = db.gamePlan; regions = enabled nodes;
 * the only game add-on (dedicated IPv4) from its admin-set price.
 *
 * Catalogue families WITHOUT active plans (e.g. schedule1, the Plutonium
 * titles, and on staging dayz/armareforger/cs16/ets2/ats) are left out
 * everywhere: they can't be ordered, so the hub doesn't sell them.
 */

// The design's configurator row: its popular picks, in its order (families
// without plans drop out; every other sellable game is in "More games").
const POPULAR = ["minecraft", "rust", "valheim", "palworld", "cs2", "projectzomboid", "ark", "sdtd", "enshrouded", "sonsoftheforest", "satisfactory", "terraria", "dayz", "conan", "vrising", "gmod"];
const FAN = ["valheim", "minecraft", "rust", "palworld", "ark", "cs2", "sdtd"];

const priceOf = (t: RealTier) => t.i ?? t.p;
const list = (xs: string[]) => (xs.length <= 1 ? xs.join("") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);

async function data() {
  const [games, regions, ipCents, modFams] = await Promise.all([sellableGames(), deployRegions(), dedicatedIpMonthlyCents(), listCatalogFamilies()]);
  if (!games.length) throw new Error("nxm /game-servers: no sellable games");
  if (!regions.length) throw new Error("nxm /game-servers: no enabled nodes");
  const tiers = await tiersByFamily(regions.map((r) => r.code));
  return { games, regions, ipCents, modFams, tiers };
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const { games, regions, ipCents, modFams, tiers } = await data();
  const fam = new Set(games.map((g) => g.family));
  const from = usd(Math.min(...games.map((g) => g.fromCents)));
  const art = Object.fromEntries(games.map((g) => [g.family, gameArt(g.family)]));
  const withCover = games.filter((g) => art[g.family].cover);

  // hero cover wall: five columns, each doubled for the seamless loop
  const cols = [0, 1, 2, 3, 4].map((c) => withCover.filter((_, i) => i % 5 === c));
  const wall = cols.map((col) => `<div class="gh-col">${[...col, ...col].map((g) => `<img data-k="${g.family}" src="${esc(art[g.family].cover!)}" alt="" width="360" height="520" decoding="async">`).join("")}</div>`).join("");
  const continents = [...new Set(regions.map((r) => r.info?.continent ?? r.label))];

  // configurator
  const pop = POPULAR.filter((f) => fam.has(f));
  const rest = games.filter((g) => !pop.includes(g.family));
  const first = games.find((g) => g.family === "minecraft") ?? games[0];
  const cfgGames = Object.fromEntries(games.map((g) => {
    const ts = tiers.get(g.family)!;
    const slots = ts.map((t) => t.slots).filter((s): s is number => s != null);
    return [g.family, { n: g.name, g: g.genres[0] ?? "Game server", img: art[g.family].cover, max: slots.length ? Math.max(...slots) : 32,
      t: ts.map((t) => ({ ram: t.ram, slots: t.slots, p: t.p, i: t.i, href: t.href })) }];
  }));
  const ft = tiers.get(first.family)!;
  const players = Math.min(10, cfgGames[first.family].max);
  const rec = ft.find((t) => t.slots == null || t.slots >= players) ?? ft[ft.length - 1];
  const R0 = regions[0];
  const tile = (f: string) => `<button type="button" class="cg" data-k="${f}" aria-pressed="${f === first.family}">${art[f].cover ? `<img src="${esc(art[f].cover!)}" alt="" width="360" height="520" loading="lazy">` : ""}<span>${esc(cfgGames[f].n)}</span></button>`;
  const addons = ipCents > 0
    ? `<label class="cfg-add"><input type="checkbox" id="a-ip"><span><b>Dedicated IPv4</b><small>Your own public IP</small></span><em>+${usd(ipCents)}</em></label>`
    : `<label class="cfg-add"><input type="checkbox" id="a-ip" checked disabled><span><b>Dedicated IPv4</b><small>Your own public IP</small></span><em>Included</em></label>`;

  // library
  const genres = GENRE_ORDER.filter((g) => games.some((x) => x.genres.includes(g)));
