import "server-only";
import { GENRE_ORDER } from "@/lib/games";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { BACKUP_FREE_KEEP } from "@/lib/backup-tiers";
import { INSTALLABLE_FAMILIES } from "@/lib/mod-install-support";
import { listCatalogFamilies } from "@/lib/mods-catalog";
import { DEPLOY_PARAM } from "@/lib/deploy-intent";
import { esc, productLd, usd, type NxmLoad } from "./lib";
import { deployRegions, gameArt, money, sellableGames, staged, tiersByFamily, type RealTier } from "./games-lib";

/**
 * /game-servers — the hub (build_games2.py). Every game, count, price, tier,
 * region and cover comes from the system at request time:
 * sellable games = families with active db.gamePlan rows (lib/games.ts names,
 * genres and art); tiers per game = db.gamePlan; regions = enabled nodes;
 * the only game add-on (dedicated IPv4) from its admin-set price.
 *
 * Catalogue families WITHOUT active plans (e.g. schedule1, the Plutonium
 * titles, and on staging dayz/armareforger/cs16/ets2/ats) are left out
 * everywhere: they can't be ordered, so the hub doesn't sell them.
 */

// The design's configurator row: its popular picks, in its order (families
// without plans drop out; every other sellable game is in "More games").
const POPULAR = ["minecraft", "rust", "valheim", "palworld", "cs2", "projectzomboid", "ark", "sdtd", "enshrouded", "sonsoftheforest", "satisfactory", "terraria", "dayz", "conan", "vrising", "gmod"];
const FAN = ["valheim", "minecraft", "rust", "palworld", "ark", "cs2", "sdtd"];

const priceOf = (t: RealTier) => t.i ?? t.p;
const list = (xs: string[]) => (xs.length <= 1 ? xs.join("") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);

async function data() {
  const [games, regions, ipCents, modFams] = await Promise.all([sellableGames(), deployRegions(), dedicatedIpMonthlyCents(), listCatalogFamilies()]);
  if (!games.length) throw new Error("nxm /game-servers: no sellable games");
  if (!regions.length) throw new Error("nxm /game-servers: no enabled nodes");
  const tiers = await tiersByFamily(regions.map((r) => r.code));
  return { games, regions, ipCents, modFams, tiers };
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const { games, regions, ipCents, modFams, tiers } = await data();
  const fam = new Set(games.map((g) => g.family));
  const from = usd(Math.min(...games.map((g) => g.fromCents)));
  const art = Object.fromEntries(games.map((g) => [g.family, gameArt(g.family)]));
  const withCover = games.filter((g) => art[g.family].cover);

  // hero cover wall: five columns, each doubled for the seamless loop
  const cols = [0, 1, 2, 3, 4].map((c) => withCover.filter((_, i) => i % 5 === c));
  const wall = cols.map((col) => `<div class="gh-col">${[...col, ...col].map((g) => `<img data-k="${g.family}" src="${esc(art[g.family].cover!)}" alt="" width="360" height="520" decoding="async">`).join("")}</div>`).join("");
  const continents = [...new Set(regions.map((r) => r.info?.continent ?? r.label))];

  // configurator
  const pop = POPULAR.filter((f) => fam.has(f));
  const rest = games.filter((g) => !pop.includes(g.family));
  const first = games.find((g) => g.family === "minecraft") ?? games[0];
  const cfgGames = Object.fromEntries(games.map((g) => {
    const ts = tiers.get(g.family)!;
    const slots = ts.map((t) => t.slots).filter((s): s is number => s != null);
    return [g.family, { n: g.name, g: g.genres[0] ?? "Game server", img: art[g.family].cover, max: slots.length ? Math.max(...slots) : 32,
      t: ts.map((t) => ({ ram: t.ram, slots: t.slots, p: t.p, i: t.i, href: t.href })) }];
  }));
  const ft = tiers.get(first.family)!;
  const players = Math.min(10, cfgGames[first.family].max);
  const rec = ft.find((t) => t.slots == null || t.slots >= players) ?? ft[ft.length - 1];
  const R0 = regions[0];
  const tile = (f: string) => `<button type="button" class="cg" data-k="${f}" aria-pressed="${f === first.family}">${art[f].cover ? `<img src="${esc(art[f].cover!)}" alt="" width="360" height="520" loading="lazy">` : ""}<span>${esc(cfgGames[f].n)}</span></button>`;
  const addons = ipCents > 0
    ? `<label class="cfg-add"><input type="checkbox" id="a-ip"><span><b>Dedicated IPv4</b><small>Your own public IP</small></span><em>+${usd(ipCents)}</em></label>`
    : `<label class="cfg-add"><input type="checkbox" id="a-ip" checked disabled><span><b>Dedicated IPv4</b><small>Your own public IP</small></span><em>Included</em></label>`;

  // library
  const genres = GENRE_ORDER.filter((g) => games.some((x) => x.genres.includes(g)));
  const cards = games.map((g) => `<a class="gl-card" href="${esc(g.route ? staged(g.route) : "#configure")}" data-key="${g.family}" data-cat="${esc(g.genres.map((x) => x.toLowerCase()).join(" "))}" data-name="${esc(g.name.toLowerCase())}">${art[g.family].lib ? `<img src="${esc(art[g.family].lib!)}" alt="" width="480" height="270" loading="lazy" decoding="async">` : ""}${g.genres[0] ? `<span class="gl-tag">${esc(g.genres[0])}</span>` : ""}<span class="gl-go">Price it</span><span class="gl-body"><span class="gl-name">${esc(g.name)}</span>${g.maxSlots ? `<span class="gl-pl">Up to ${g.maxSlots} players</span>` : ""}</span></a>`).join("");

  // tour (the size + payment screens are HTML in the design, so they show real tiers)
  const tg = first, tts = ft, pick = tts.find((t) => t.featured) ?? tts[Math.min(1, tts.length - 1)];
  const szCard = (t: RealTier) => `<div class="sz-c${t === pick ? " on" : ""}"${t === pick ? ' id="sz-pick"' : ""}>${t === pick ? "<i>Recommended</i>" : ""}<b>${t.ram} GB</b><span>${t.slots != null ? `${t.slots} player slots` : "&nbsp;"}</span><em>${money(priceOf(t))}<small>/mo</small></em></div>`;
  const shown = tts.slice(0, 2).includes(pick) ? tts.slice(0, 2) : [tts[0], pick];
  const big = tts[tts.length - 1];
  const size = `<p class="sz-s">${esc(tg.name)}, sized by memory and player slots.</p>
                <div class="sz-cards">${shown.map(szCard).join("")}${tts.length > shown.length ? `<div class="sz-c ghost"><b>More sizes</b><span>Up to ${big.ram} GB for big communities</span><em>&nbsp;</em></div>` : ""}</div>
                <div class="sz-foot"><span>${esc(tg.name)}, ${pick.ram} GB${pick.slots != null ? `, ${pick.slots} slots` : ""}</span><b>${money(priceOf(pick))}</b><span class="sz-next">Next</span></div>`;
  const pay = `<div class="pay-item">${art[tg.family].cover ? `<img src="${esc(art[tg.family].cover!)}" alt="">` : ""}<div><b>${esc(tg.name)}</b><small>${pick.ram} GB${pick.slots != null ? `, ${pick.slots} slots` : ""}, ${esc(R0.label)}</small></div><em>${money(priceOf(pick))}</em></div>
                  ${ipCents > 0 ? `<div class="pay-row"><span>Dedicated IPv4</span><em>+${usd(ipCents)}, not added</em></div>` : ""}
                  <div class="pay-tot"><span>Due today</span><b>${money(priceOf(pick))}</b></div>
                  <p class="pay-renew">Renews monthly. Cancel whenever you like.</p>
                  <span class="pay-btn" id="pay-btn"><span class="pb-a">Pay ${money(priceOf(pick))} and deploy</span>`;

  // FAQ
  const named = pop.slice(0, 6).map((f) => cfgGames[f].n);
  const modGames = modFams.filter((m) => fam.has(m.family));
  const modTotal = modGames.reduce((a, m) => a + m.count, 0);
  const oneClick = games.filter((g) => INSTALLABLE_FAMILIES.has(g.family)).length;
  const Q: [string, string][] = [
    ["Which games can I host?", `${games.length} titles${named.length >= 6 ? `, from ${list(named.slice(0, 3))} to ${list(named.slice(3, 6))}` : named.length ? `, including ${list(named)}` : ""}. Each one comes pre-configured, so you pick a game and deploy.`],
    ["Can I install mods and plugins?", `Yes. NxLabs lists ${modTotal.toLocaleString("en-US")} mods and plugins for ${modGames.length} of these games, and for ${oneClick} of them supported mods install straight onto your server from the panel. Every server also gives you full file access for anything else.`],
    ["Where are the servers?", `Game servers run in ${list(regions.map((r) => r.label))}. You pick the region when you deploy.`],
    ["What happens if my server gets attacked?", "Every game server includes DDoS protection. Attack traffic is filtered at the network edge before it reaches your server."],
    ["Are my worlds backed up?", `Switch on scheduled backups in your server’s panel and it keeps the last ${BACKUP_FREE_KEEP} daily restore points, ready to roll back to.`],
    ["Can I upgrade my server later?", "Yes. Resize whenever you need more memory or player slots, right from the panel."],
  ];
  const faq = Q.map(([q, a], i) => `<details${i === 0 ? " open" : ""}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("");
  const fanGames = [...FAN.filter((f) => fam.has(f) && art[f].cover), ...withCover.map((g) => g.family)].filter((f, i, a) => a.indexOf(f) === i).slice(0, 7);
  const toastRegions = regions.map((r) => r.label);

  return {
    slots: {
      "wall:html": wall, "games.n": String(games.length), "games.from": from,
      "regions.n": String(regions.length), "regions.label": `game region${regions.length === 1 ? "" : "s"}, ${list(continents)}`,
      "toast.img": art[first.family].cover ?? "", "toast.name": first.name, "toast.text": `ready to deploy in ${R0.label}`,
      "cfg.tiles:html": pop.map(tile).join(""),
      "cfg.more:html": `<option value="">Choose another game</option>${rest.map((g) => `<option value="${g.family}">${esc(g.name)}</option>`).join("")}`,
      "cfg.img": cfgGames[first.family].img ?? "", "cfg.genre": cfgGames[first.family].g, "cfg.name": first.name,
      "cfg.hint": `Recommended: ${rec.ram} GB${rec.slots != null ? ` for up to ${rec.slots} players` : ""}`,
      "cfg.max": String(cfgGames[first.family].max), "cfg.players": String(players),
      "cfg.mem": `${rec.ram} GB`, "cfg.slots": rec.slots != null ? String(rec.slots) : "—",
      "cfg.regions:html": regions.map((r, i) => `<button type="button" aria-pressed="${i === 0}" data-r="${esc(r.code)}">${r.cc ? `<span class="flag flag-${r.cc}"></span>` : ""}${esc(r.label)}</button>`).join(""),
      "cfg.addons:html": addons, "cfg.total": money(priceOf(rec)), "cfg.href": rec.href[R0.code], "cfg.cta": `Deploy ${first.name}`,
      "regions.lede": `Game servers run in ${list(regions.map((r) => `${r.label} for ${r.info?.continent ?? r.city}`))}.`,
      "rf.cards:html": regions.map((r) => `<div class="rf-card" id="rf-${esc(r.code)}"><div class="rf-top">${r.cc ? `<span class="flag flag-lg flag-${r.cc}"></span>` : ""}<div><b>${esc(r.label)}</b><small>${esc(r.city)}${r.info ? `, ${esc(r.info.continent)}` : ""}</small></div><em class="rf-best">Best fit</em></div><div class="rf-ms"><b id="rf-km-${esc(r.code)}">&nbsp;</b><span>from your players</span></div><div class="rf-bar"><i id="rf-bar-${esc(r.code)}"></i></div></div>`).join("")
        + `<p class="rf-note">Straight-line distance. Closer usually means lower ping; real latency also depends on your players' connections.</p>`,
      "lib.filters:html": `<button type="button" aria-pressed="true" data-f="all">All</button>${genres.map((g) => `<button type="button" aria-pressed="false" data-f="${g.toLowerCase()}">${g}</button>`).join("")}`,
      "lib.cards:html": cards, "lib.count": `Showing all ${games.length} games. More are added regularly.`,
      "tour.regions": list(regions.map((r) => `${r.label} for ${r.info?.continent ?? r.city}`)) + ".",
      "tour.size:html": size, "tour.pay:html": pay,
      "mods.href": staged("/mods"),
      "faq:html": faq,
      "fan:html": fanGames.map((f, i) => `<img style="--i:${i}" src="${esc(art[f].cover!)}" alt="" width="360" height="520" loading="lazy">`).join(""),
    },
    data: {
      toasts: games.filter((g) => art[g.family].cover).flatMap((g, i) => [{ img: art[g.family].cover, name: g.name, text: `ready to deploy in ${toastRegions[i % toastRegions.length]}` }]),
      cfg: { games: cfgGames, first: first.family, ip: ipCents, addonParam: DEPLOY_PARAM.addons },
      regions: regions.filter((r) => r.coords).map((r) => ({ code: r.code, label: r.label, lat: r.coords!.lat, lon: r.coords!.lon })),
      tour: [
        `The real Nxeon panel. Step 1: choose Game Servers, from ${from} a month.`,
        `Step 2: pick ${tg.name} from ${games.length} pre-configured games.`,
        `Step 3: ${pick.ram} GB${pick.slots != null ? ` and ${pick.slots} player slots` : ""}, a ${tg.name} size from the real plan list.`,
        `Step 4: pick the region closest to your players: ${list(regions.map((r) => r.label))}.`,
