import "server-only";
import { getSetting, getSettingBool, getSettingInt } from "@/lib/settings";
import { AU_ICONS } from "../_aurora/icons";
import { APP_URL } from "@/components/marketing/StructuredData";
import { esc, type NxmLoad } from "./lib";
import { deployRegions, gameRoute, money, realTiers, staged } from "./games-lib";

/**
 * /free-minecraft — the free tier's limits from the Settings the free-tier
 * actions enforce (lib/actions-free-minecraft.ts): free_minecraft_ram_mb,
 * free_minecraft_domain, free_minecraft_enabled; the paid column from the real
 * Minecraft tiers (db.gamePlan).
 */
const ROCKET = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;

async function settings() {
  const [enabled, domain, ramMb] = await Promise.all([
    getSettingBool("free_minecraft_enabled", false),
    getSetting("free_minecraft_domain", "play.nxeon.cloud"),
    getSettingInt("free_minecraft_ram_mb", 1024),
  ]);
  if (!domain || !(ramMb > 0)) throw new Error("nxm /free-minecraft: free tier settings missing");
  const gb = Math.round((ramMb / 1024) * 10) / 10;
  return { enabled, domain, ram: `${gb} GB` };
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const s = await settings();
  const regions = await deployRegions();
  const tiers = await realTiers("minecraft", regions.map((r) => r.code));
  if (!tiers.length) throw new Error("nxm /free-minecraft: no active Minecraft plans");
  const paid = staged(gameRoute("minecraft") ?? "/game-servers");
  const lo = tiers[0], hi = tiers[tiers.length - 1];
  const claimHref = s.enabled ? "/dashboard/free-minecraft" : paid;
  const claimLabel = s.enabled ? "Claim your free server" : "See paid plans";
  return {
    slots: {
      "fm.domain": s.domain,
      "fm.ram": s.ram,
      "fm.paidRange": lo.ram === hi.ram ? `Dedicated ${hi.ram} GB` : `Dedicated ${lo.ram} to ${hi.ram} GB`,
      "fm.paidFrom": `From ${money(lo.i ?? lo.p)} a month`,
      "fm.chip": s.enabled ? "No credit card, no expiry" : "Free servers are paused right now",
      "fm.claim:html": `<a class="nxm-btn au-hov" href="${esc(claimHref)}">${ROCKET}<span class="nxm-bt">${claimLabel}<span class="ar">→</span></span></a>`,
      "fm.start:html": `<a class="nxm-ghost" href="${esc(claimHref)}"><span class="nxm-bt">${s.enabled ? "Start free" : "See paid plans"}</span></a>`,
    },
    data: { domain: s.domain },
    // An explicit $0 Offer, as the live page does: $0 is this product's real price.
    jsonLd: s.enabled ? [{
      "@context": "https://schema.org", "@type": "Product", name: "Nxeon Free Minecraft Server",
      description: `A free Minecraft server on its own ${s.domain} subdomain, ${s.ram} of memory, no credit card required. Sleeps when idle, wakes on connect.`,
      brand: { "@type": "Brand", name: "Nxeon" },
      offers: { "@type": "Offer", price: "0", priceCurrency: "USD", availability: "https://schema.org/InStock", url: `${APP_URL}/free-minecraft` },
    }] : [],
  };
}

export async function meta(_p: Record<string, string>) {
  const s = await settings();
  return {
    description: `Host a real free Minecraft server on your own ${s.domain} subdomain: ${s.ram} of memory, no credit card, no trial countdown, no queue to start playing. Sleeps when idle, wakes in seconds, upgrade to a dedicated server anytime.`,
  };
}

