    "custom.sized": "Sized to your player count",
    "custom.lede": `Need ${c.name} servers for a big community? Tell us what you’re running and we’ll size and quote a custom setup.`,
    "loaders:html": loadersHtml(c), "mods:html": modsHtml(c),
    "more:html": moreHtml(c), "faq:html": faq,
    "flow.pick": "", "flow.boot": "",
    "final.h": `Looking for ${c.name} hosting?`,
    "final.alt:html": `<a class="nxm-glassbtn" href="${esc(hub)}"><span class="nxm-bt">See every game</span></a>`,
