new = r'''CONFIGURATOR = r"""/* ============ Configurator: game-by-game pricing (real tiers, db.gamePlan) ============ */
(function configurator() {
  const bars = $('#cfg-bars'); if (!bars) return;
  const G = __NXM.cfg.games, IP = __NXM.cfg.ip, AP = __NXM.cfg.addonParam, CX = __NXM.cfg.custom;
  const tiles = $$('.cg'), pl = $('#cfg-pl'), plv = $('#cfg-plv'), grid = $('#gx-grid'), plot = $('#gx-plot'), sum = $('.cfg-sum');
  const regBtns = $$('.cfg-reg button'), aIp = $('#a-ip');
  let game = __NXM.cfg.first, sz = G[game], sel = 0, manual = false, shown = 0, cbs = [], ax = 10;
  let reg = (regBtns.find(b => b.getAttribute('aria-pressed') === 'true') || regBtns[0]).dataset.r;
  const money = v => '$' + v.toFixed(2), price = t => t.i != null ? t.i : t.p;
  const fits = (t, p) => t.slots == null || t.slots >= p;
  const recFor = p => { const i = sz.t.findIndex(t => fits(t, p)); return i < 0 ? sz.t.length - 1 : i; };
  const cta = $('#s-cta'), ctaT = $('.nxm-bt', cta) || cta;
  function tween(to) {
    const el = $('#s-total'), from = shown; shown = to; if (RM) { el.textContent = money(to); return; }
    const t0 = performance.now(); const step = now => { const k = Math.min(1, (now - t0) / 450), e = 1 - Math.pow(1 - k, 3); el.textContent = money(from + (to - from) * e); if (k < 1) requestAnimationFrame(step); }; requestAnimationFrame(step);
  }
  function href(t) { let h = t.href[reg]; if (aIp && aIp.checked && IP > 0) { const u = new URL(h, location.origin); u.searchParams.set(AP, 'ip'); h = u.pathname + u.search; } return h; }
  function show(t, preview) {
    $('#s-mem').textContent = t.ram + ' GB'; $('#s-slots').textContent = t.slots != null ? t.slots : '—';
    sum.classList.toggle('is-preview', !!preview);
    if (preview) { $('#s-total').textContent = money(price(t) + (aIp && aIp.checked ? IP / 100 : 0)); shown = price(t) + (aIp && aIp.checked ? IP / 100 : 0); }
    else tween(price(t) + (aIp && aIp.checked ? IP / 100 : 0));
  }
  function line() {
    const p = +pl.value, l = $('.gx-line', grid);
    if (l) { l.style.setProperty('--y', Math.min(1, p / ax).toFixed(4)); $('em', l).textContent = p + (p === 1 ? ' player' : ' players'); }
  }
  function render() {
    const p = +pl.value, rec = recFor(p);
    if (!manual || !fits(sz.t[sel], p)) { sel = rec; manual = false; }
    cbs.forEach((b, i) => { const t = sz.t[i]; b.classList.toggle('rec', i === rec); b.classList.toggle('sel', i === sel); b.classList.toggle('short', !fits(t, p));
